// The slow half of Re-Entry's landing check — whole-number + − × ÷ ^ (solver.reachX: ~35–80 ms median, up to
// ~0.8 s worst on desktop) — runs here, off the main thread, so a phone never freezes while you play (contrarian
// build review M1). One memo for the whole session.
import { makeSolver } from './solver';

const solver = makeSolver();
self.onmessage = (e) => {
  const { id, dice, target } = e.data;
  self.postMessage({ id, ok: solver.reachX(dice).has(target) });
};
